const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const body = $input.first().json.body ?? {};
const batchId = typeof body.batch_id === 'string' ? body.batch_id : '';
return [{ json: { batch_id: batchId, batch_id_valid: UUID.test(batchId) } }];

const HIGH_CONFIDENCE_CUTOFF = 0.7;
const AFFORDABILITY_CAP = 0.65;
const INDICATIVE_LOAN_RUPEES = 500000;
const INDICATIVE_TENURE_MONTHS = 60;

function rupees(amount) {
  return '₹' + Math.round(amount).toLocaleString('en-IN');
}

function monthlyEmi(principal, annualRatePct, months) {
  const monthlyRate = annualRatePct / 1200;
  if (monthlyRate === 0) {
    return principal / months;
  }
  const growth = (1 + monthlyRate) ** months;
  return (principal * monthlyRate * growth) / (growth - 1);
}

function publishedRate(product) {
  if (product.interest_rate_max !== null && product.interest_rate_max !== undefined) {
    return { pct: Number(product.interest_rate_max), basis: 'top published rate' };
  }
  if (product.interest_rate_min !== null && product.interest_rate_min !== undefined) {
    return { pct: Number(product.interest_rate_min), basis: 'published starting rate' };
  }
  return null;
}

function affordability(product) {
  const rate = publishedRate(product);
  if (rate === null) {
    return { indicative_emi: null, emi_note: null };
  }
  const emi = Math.round(monthlyEmi(INDICATIVE_LOAN_RUPEES, rate.pct, INDICATIVE_TENURE_MONTHS) * 100) / 100;
  return {
    indicative_emi: emi,
    emi_note: `indicative EMI ${rupees(emi)} for ${rupees(INDICATIVE_LOAN_RUPEES)} over ${INDICATIVE_TENURE_MONTHS} months at the ${rate.basis} of ${rate.pct}% p.a.`,
  };
}

function ruleCard(product) {
  const confidence = product.parse_confidence === null ? 0 : Number(product.parse_confidence);
  const fullyStructured = confidence >= HIGH_CONFIDENCE_CUTOFF;
  return {
    product_id: Number(product.product_id),
    parse_confidence: confidence,
    near_miss_policy: fullyStructured ? 'clear_reject' : 'borderline',
    affordability_cap: AFFORDABILITY_CAP,
    ...affordability(product),
    conditions_note: fullyStructured
      ? null
      : `The lender's criteria are only partly captured in structured fields (parse confidence ${confidence.toFixed(2)}), so this is indicative; the lender's full conditions still apply.`,
  };
}

const run = $input.first().json;

return [
  {
    json: {
      run_id: run.run_id,
      batch_id: run.batch_id,
      stage2_started_at: run.stage2_started_at,
      cards: (run.products || []).map(ruleCard),
    },
  },
];

const MODEL = 'openai/gpt-oss-120b';
const MAX_COHORTS_PER_REQUEST = 16;
const DAILY_TOKEN_BUDGET = 150000;
const MAX_CALLS_PER_RUN = 30;
const CHARS_PER_TOKEN_ESTIMATE = 3;
const COMPLETION_TOKENS_BASE = 600;
const COMPLETION_TOKENS_PER_COHORT = 100;

const SYSTEM_PROMPT = [
  "You review borderline personal-loan applicants against one lender's published eligibility text.",
  'Each cohort is a group of applicants who meet every structured criterion of this product except the shortfall described for the cohort, which is within 5% of the figure the lender states.',
  "For each cohort decide whether the lender's own wording still allows an applicant at the cohort's worst value.",
  '1. Use only the lender text in the message. Do not use outside knowledge about the lender.',
  '2. If any sentence states the figure as a requirement (for example minimum, must, you need, at least, to be eligible), the shortfall is not allowed: eligible = false, even when another sentence sounds softer.',
  '3. If the text presents the figure only as a preference or a favourable factor (for example preferred, ideal, favourable, may improve), decide whether the wording leaves room for an applicant at the worst value given.',
  '4. The verdict covers every applicant in the cohort, so judge the worst value, not the band as a whole.',
  "5. reason: one sentence of at most 200 characters that quotes the lender's words you relied on.",
  '6. Return exactly one verdict for every cohort id in the message and no other ids.',
].join('\n');

const FEATURE_LABELS = { credit_score: 'credit score', monthly_income: 'net monthly income' };
const SIDE_OF_FIGURE = { minimum: 'below', maximum: 'above' };

function describeValue(feature, value) {
  const number = Number(value).toLocaleString('en-IN');
  return feature === 'monthly_income' ? `Rs ${number}` : number;
}

function describeShortfall(shortfall) {
  const label = FEATURE_LABELS[shortfall.feature];
  const value = (v) => describeValue(shortfall.feature, v);
  const band = `${value(shortfall.band_low)} to ${value(shortfall.band_high)}`;
  return `${label} ${band}, ${SIDE_OF_FIGURE[shortfall.bound]} the lender's figure of ${value(shortfall.threshold)} (worst value ${value(shortfall.worst_value)})`;
}

function cohortLine(cohort, cohortId) {
  const shortfalls = cohort.shortfalls.map(describeShortfall).join('; and ');
  return `${cohortId}: ${cohort.employment_status} applicants; ${shortfalls}.`;
}

function responseSchema(cohortIds) {
  return {
    type: 'object',
    properties: {
      verdicts: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            cohort_id: { type: 'string', enum: cohortIds },
            eligible: { type: 'boolean' },
            reason: { type: 'string' },
          },
          required: ['cohort_id', 'eligible', 'reason'],
          additionalProperties: false,
        },
      },
    },
    required: ['verdicts'],
    additionalProperties: false,
  };
}

function groqRequest(product, members) {
  const cohortIds = members.map((m) => m.cohort_id);
  const userContent = [
    `Lender: ${product.source}`,
    `Product: ${product.product_name}`,
    'Lender eligibility text:',
    product.criteria_text,
    '',
    'Cohorts:',
    ...members.map((m) => cohortLine(m.cohort, m.cohort_id)),
  ].join('\n');
  return {
    model: MODEL,
    temperature: 0,
    reasoning_effort: 'low',
    include_reasoning: false,
    max_completion_tokens: COMPLETION_TOKENS_BASE + COMPLETION_TOKENS_PER_COHORT * members.length,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: userContent },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: { name: 'cohort_verdicts', strict: true, schema: responseSchema(cohortIds) },
    },
  };
}

function estimatedTokens(request) {
  const promptChars = request.messages.reduce((sum, m) => sum + m.content.length, 0)
    + JSON.stringify(request.response_format).length;
  return Math.ceil(promptChars / CHARS_PER_TOKEN_ESTIMATE) + request.max_completion_tokens;
}

function chunk(list, size) {
  const chunks = [];
  for (let i = 0; i < list.length; i += size) {
    chunks.push(list.slice(i, i + size));
  }
  return chunks;
}

function plannedRequests(cohorts, products) {
  const productsById = new Map(products.map((p) => [Number(p.product_id), p]));
  const byProduct = new Map();
  for (const cohort of cohorts) {
    const key = Number(cohort.product_id);
    if (!byProduct.has(key)) {
      byProduct.set(key, []);
    }
    byProduct.get(key).push(cohort);
  }
  const requests = [];
  for (const [productId, productCohorts] of byProduct) {
    for (const group of chunk(productCohorts, MAX_COHORTS_PER_REQUEST)) {
      const members = group.map((cohort, i) => ({ cohort, cohort_id: `c${String(i + 1).padStart(2, '0')}` }));
      const request = groqRequest(productsById.get(productId), members);
      requests.push({
        product_id: productId,
        cohorts: members.map((m) => ({
          cohort_id: m.cohort_id,
          cohort_key: m.cohort.cohort_key,
          content_hash: m.cohort.content_hash,
          members: Number(m.cohort.members),
        })),
        groq_request: request,
        estimated_tokens: estimatedTokens(request),
      });
    }
  }
  return requests;
}

function unresolved(cohorts, outcome, reason) {
  return cohorts.map((c) => ({ cohort_key: c.cohort_key, outcome, reason }));
}

function applyBudget(requests, usedTokens) {
  let remaining = DAILY_TOKEN_BUDGET - usedTokens;
  const send = [];
  const skipped = [];
  for (const request of requests) {
    if (send.length >= MAX_CALLS_PER_RUN) {
      skipped.push(...unresolved(request.cohorts, 'unresolved_budget',
        `Not asked: the run already planned its maximum of ${MAX_CALLS_PER_RUN} LLM calls.`));
    } else if (request.estimated_tokens > remaining) {
      skipped.push(...unresolved(request.cohorts, 'unresolved_budget',
        `Not asked: the daily Stage 3 token budget has ${Math.max(remaining, 0)} of ${DAILY_TOKEN_BUDGET} tokens left and this request needs an estimated ${request.estimated_tokens}.`));
    } else {
      remaining -= request.estimated_tokens;
      send.push(request);
    }
  }
  return { send, skipped, remaining };
}

const run = $input.first().json;
const cohorts = run.cohorts || [];
const unhashed = cohorts.filter((c) => !c.content_hash);
const askable = cohorts.filter((c) => c.content_hash && !c.cached);
const usedTokens = Number((run.llm_usage_24h || {})[MODEL]?.tokens ?? 0);
const budget = applyBudget(plannedRequests(askable, run.products || []), usedTokens);

return [
  {
    json: {
      run_id: run.run_id,
      batch_id: run.batch_id,
      stage3_started_at: run.stage3_started_at,
      model: MODEL,
      cohort_count: cohorts.length,
      cache_hits: cohorts.filter((c) => c.cached).length,
      requests: budget.send.map((request, i) => ({
        ...request,
        request_no: i + 1,
        run_id: run.run_id,
        batch_id: run.batch_id,
      })),
      unresolved: [
        ...unresolved(unhashed, 'unresolved_error',
          'The product has no content hash, so a verdict could not be cached against its text.'),
        ...budget.skipped,
      ],
      budget: {
        daily_token_budget: DAILY_TOKEN_BUDGET,
        used_tokens_24h: usedTokens,
        max_calls_per_run: MAX_CALLS_PER_RUN,
        planned_calls: budget.send.length,
        estimated_tokens: budget.send.reduce((sum, r) => sum + r.estimated_tokens, 0),
      },
    },
  },
];

const MAX_REASON_CHARS = 300;
const MAX_ERROR_CHARS = 300;

const build = $('Stage 3 · Build LLM requests').first().json;
const requests = build.requests || [];
const responses = requests.length > 0 ? $input.all().map((item) => item.json) : [];

function clip(text, limit) {
  return String(text).slice(0, limit);
}

function unresolvedAll(request, reason) {
  return {
    verdicts: [],
    unresolved: request.cohorts.map((c) => ({
      cohort_key: c.cohort_key,
      outcome: 'unresolved_error',
      reason: clip(reason, MAX_ERROR_CHARS),
    })),
  };
}

function httpFailure(response) {
  const status = response.statusCode ?? 0;
  const message = response.body?.error?.message;
  if (status === 429) {
    const retryAfter = response.headers?.['retry-after'] ?? 'not sent';
    return `Groq rate limited (HTTP 429), retry-after ${retryAfter} s${message ? ': ' + message : ''}`;
  }
  if (status) {
    return `Groq HTTP ${status}${message ? ': ' + message : ''}`;
  }
  return `No response from Groq: ${response.error?.message ?? response.error ?? 'unknown error'}`;
}

function parsedAnswer(response) {
  const content = response.body?.choices?.[0]?.message?.content;
  if (typeof content !== 'string') {
    throw new Error('the reply has no message content');
  }
  let answer;
  try {
    answer = JSON.parse(content);
  } catch {
    throw new Error('the message content is not JSON');
  }
  if (answer === null || typeof answer !== 'object' || !Array.isArray(answer.verdicts)) {
    throw new Error('the answer has no verdicts array');
  }
  return answer.verdicts;
}

function wellFormed(verdict) {
  return verdict !== null
    && typeof verdict === 'object'
    && typeof verdict.cohort_id === 'string'
    && typeof verdict.eligible === 'boolean'
    && typeof verdict.reason === 'string'
    && verdict.reason.trim() !== '';
}

function judged(request, response) {
  if ((response.statusCode ?? 0) !== 200) {
    return unresolvedAll(request, httpFailure(response));
  }
  let answers;
  try {
    answers = parsedAnswer(response);
  } catch (error) {
    return unresolvedAll(request, `Groq answer was not valid: ${error.message}`);
  }
  const model = response.body.model || request.groq_request.model;
  const byId = new Map();
  for (const verdict of answers.filter(wellFormed)) {
    byId.set(verdict.cohort_id, [...(byId.get(verdict.cohort_id) || []), verdict]);
  }
  const result = { verdicts: [], unresolved: [] };
  for (const cohort of request.cohorts) {
    const found = byId.get(cohort.cohort_id) || [];
    if (found.length === 1) {
      result.verdicts.push({
        cohort_key: cohort.cohort_key,
        product_content_hash: cohort.content_hash,
        eligible: found[0].eligible,
        reason: clip(found[0].reason.trim(), MAX_REASON_CHARS),
        model,
      });
    } else {
      result.unresolved.push({
        cohort_key: cohort.cohort_key,
        outcome: 'unresolved_error',
        reason: found.length === 0
          ? 'Groq returned no well-formed verdict for this cohort.'
          : `Groq returned ${found.length} verdicts for this cohort, so none is used.`,
      });
    }
  }
  return result;
}

function usedTokens(response) {
  const usage = response.body?.usage ?? {};
  return (usage.prompt_tokens ?? 0) + (usage.completion_tokens ?? 0);
}

const results = requests.map((request, i) => judged(request, responses[i] ?? { error: 'no output item for this request' }));

return [
  {
    json: {
      run_id: build.run_id,
      batch_id: build.batch_id,
      stage3_started_at: build.stage3_started_at,
      cohort_count: build.cohort_count,
      cache_hits: build.cache_hits,
      llm_calls: responses.length,
      llm_tokens: responses.reduce((sum, response) => sum + usedTokens(response), 0),
      verdicts: results.flatMap((r) => r.verdicts),
      unresolved: [...(build.unresolved || []), ...results.flatMap((r) => r.unresolved)],
    },
  },
];
